function retireForm(r){const reason=h("textarea",{id:"retire-reason",rows:3,maxLength:1000,required:true,placeholder:"Explica por qué debería retirarse esta responsabilidad."});const form=h("form",{onSubmit:e=>{e.preventDefault();if(!form.reportValidity())return;mutate(async()=>{await api(`/api/responsibilities/${r.id}/motions`,{kind:"retire",reason:reason.value.trim()});modal.close();boardScope="roles";boardFilters.roles=freshFilters();tab="votes";},"Retiro propuesto. La función sigue vigente hasta que se apruebe.");}},h("p",{class:"notice warning"},`«${r.title}» seguirá vigente hasta que se apruebe su retiro. El acuerdo y los votos anteriores se conservarán.`),field("Motivo del retiro",reason),h("div",{class:"modal-actions"},button("Volver",()=>modal.close(),"ghost"),h("button",{class:"button primary",type:"submit","data-mutation":"true"},"Proponer retiro")));showModal("Proponer el retiro de una función",form);}
